import("stdfaust.lib");

freq = hslider("freq", 440, 20, 8000, 0.01);
gain = hslider("gain", 0.5, 0, 1, 0.01);
gate = button("gate");

// Partial frequencies
f1 = freq * 1.05;
f2 = freq * 1.10;
f3 = freq * 1.15;

// Partial amplitudes
a1 = hslider("Amp1", 0.3, 0, 1, 0.01);
a2 = hslider("Amp2", 0.2, 0, 1, 0.01);
a3 = hslider("Amp3", 0.1, 0, 1, 0.01);

// Partial attack times
at1 = hslider("Attack1[unit:s]", 0.01, 0.001, 0.1, 0.001);
at2 = hslider("Attack2[unit:s]", 0.01, 0.001, 0.1, 0.001);
at3 = hslider("Attack3[unit:s]", 0.01, 0.001, 0.1, 0.001);

// Partial decay times
dt1 = hslider("Decay1[unit:s]", 2, 1, 8, 0.01);
dt2 = hslider("Decay2[unit:s]", 2, 1, 8, 0.01);
dt3 = hslider("Decay3[unit:s]", 2, 1, 8, 0.01);

// Envelopes
env1 = en.adsr(at1, dt1, 1, 0.01, gate);
env2 = en.adsr(at2, dt2, 1, 0.01, gate);
env3 = en.adsr(at3, dt3, 1, 0.01, gate);

// Oscillators
osc1 = os.sine(f1) * a1 * env1;
osc2 = os.sine(f2) * a2 * env2;
osc3 = os.sine(f3) * a3 * env3;

// Summing the oscillators
process = (osc1 + osc2 + osc3) * gain;

